L2_1.m_Talk_VTN = L3_1
L3_1 = "<color=#ffd34c>\231\142\176\229\156\168\229\143\170\232\131\189\229\139\137\229\188\186\229\129\154\228\184\128\228\186\155\230\128\165\230\149\145\230\142\170\230\150\189\239\188\140\228\189\134\226\128\166\226\128\166\229\186\148\232\175\165\230\146\145\228\184\141\228\186\134\229\164\170\228\185\133\227\128\130</color>"
L2_1.m_Talk_SCN = L3_1
L3_1 = "<color=#ffd34c>Wir versuchen unser Bestes, um mit Erster Hilfe etwas Zeit zu gewinnen\194\160\226\128\147 aber sie werden nicht lange durchhalten.</color>"
